@mcp.tool()
def wp_bulk_comment_action(
    ids: list,
    action: str,
) -> dict:
    """Apply an action to multiple comments at once (approve, spam, delete, trash)"""
    status_map = {"approve": "approved", "trash": "trash", "spam": "spam"}
    results = []
    if action == "delete":
        for cid in ids:
            results.append(_wp().delete(f"/wp/v2/comments/{cid}", params={"force": True}))
    else:
        status = status_map.get(action, action)
        for cid in ids:
            results.append(_wp().post(f"/wp/v2/comments/{cid}", json={"status": status}))
    return {"results": results}

