@mcp.tool()
def wp_blocks_parse(
    content: str = None,
    post_id: int = None,
    post_type: str = "post",
) -> dict:
    """Parse post_content (block markup) into a structured block tree"""
    source_content = content
    if source_content is None:
        if post_id is None:
            raise ValueError("Either content or post_id is required")
        source_content, _ = _wp_get_editable_content(post_id, post_type)
    return {
        "post_id": post_id,
        "post_type": _elementor_content_collection(post_type),
        "blocks": _wp_parse_blocks_content(source_content),
    }

@mcp.tool()
def wp_blocks_serialize(
    blocks: list,
) -> dict:
    """Serialize a JSON block tree back to WordPress post_content string"""
    content = _wp_serialize_blocks(blocks)
    return {"content": content, "blocks": _wp_parse_blocks_content(content)}

@mcp.tool()
def wp_blocks_find(
    post_id: int,
    block_name: str,
    post_type: str = "post",
) -> dict:
    """Find blocks by name in a post's content"""
    raw_content, _ = _wp_get_editable_content(post_id, post_type)
    blocks = _wp_parse_blocks_content(raw_content)
    target = block_name.strip().lower()
    matches = [block for block in blocks if str(block.get("blockName") or "").strip().lower() in {target, f"core/{target}"}]
    return {"post_id": post_id, "post_type": _elementor_content_collection(post_type), "matches": matches}

@mcp.tool()
def wp_blocks_insert(
    post_id: int,
    block: dict,
    post_type: str = "post",
    position: int = None,
) -> dict:
    """Insert a block at a specific position in a post's content"""
    raw_content, _ = _wp_get_editable_content(post_id, post_type)
    blocks = _wp_parse_blocks_content(raw_content)
    insert_at = len(blocks) if position is None else max(0, min(position, len(blocks)))
    blocks.insert(insert_at, block)
    return _wp_save_blocks(post_id, post_type, blocks)

@mcp.tool()
def wp_blocks_update(
    post_id: int,
    index: int,
    attrs: dict,
    post_type: str = "post",
    innerHTML: str = None,
) -> dict:
    """Update block attributes at a specific index in a post"""
    raw_content, _ = _wp_get_editable_content(post_id, post_type)
    blocks = _wp_parse_blocks_content(raw_content)
    target = dict(blocks[_wp_block_index(index, blocks)] or {})
    target["attrs"] = {**(target.get("attrs") or {}), **(attrs or {})}
    if innerHTML is not None:
        target["innerHTML"] = innerHTML
    blocks[index] = target
    return _wp_save_blocks(post_id, post_type, blocks)

@mcp.tool()
def wp_blocks_remove(
    post_id: int,
    index: int,
    post_type: str = "post",
) -> dict:
    """Remove a block by index from a post's content"""
    raw_content, _ = _wp_get_editable_content(post_id, post_type)
    blocks = _wp_parse_blocks_content(raw_content)
    blocks.pop(_wp_block_index(index, blocks))
    return _wp_save_blocks(post_id, post_type, blocks)

@mcp.tool()
def wp_blocks_move(
    post_id: int,
    from_index: int,
    to_index: int,
    post_type: str = "post",
) -> dict:
    """Move a block from one position to another in a post"""
    raw_content, _ = _wp_get_editable_content(post_id, post_type)
    blocks = _wp_parse_blocks_content(raw_content)
    block = blocks.pop(_wp_block_index(from_index, blocks))
    destination = max(0, min(to_index, len(blocks)))
    blocks.insert(destination, block)
    return _wp_save_blocks(post_id, post_type, blocks)

@mcp.tool()
def wp_blocks_replace(
    post_id: int,
    index: int,
    block: dict,
    post_type: str = "post",
) -> dict:
    """Replace a block at a specific index with a new block"""
    raw_content, _ = _wp_get_editable_content(post_id, post_type)
    blocks = _wp_parse_blocks_content(raw_content)
    blocks[_wp_block_index(index, blocks)] = block
    return _wp_save_blocks(post_id, post_type, blocks)

@mcp.tool()
def wp_blocks_wrap(
    post_id: int,
    start_index: int,
    end_index: int,
    post_type: str = "post",
    wrapper: str = "group",
    wrapper_attrs: dict = None,
) -> dict:
    """Wrap one or more blocks in a group or columns block"""
    raw_content, _ = _wp_get_editable_content(post_id, post_type)
    blocks = _wp_parse_blocks_content(raw_content)
    start = _wp_block_index(start_index, blocks)
    end = _wp_block_index(end_index, blocks)
    if end < start:
        raise ValueError("end_index must be >= start_index")
    wrapper_block = {
        "blockName": wrapper,
        "attrs": wrapper_attrs or {},
        "innerHTML": _wp_serialize_blocks(blocks[start:end + 1]),
    }
    blocks[start:end + 1] = [wrapper_block]
    return _wp_save_blocks(post_id, post_type, blocks)

@mcp.tool()
def wp_blocks_batch_update(
    post_id: int,
    operations: list,
    post_type: str = "post",
) -> dict:
    """Perform multiple block operations on a post in a single save"""
    raw_content, _ = _wp_get_editable_content(post_id, post_type)
    blocks = _wp_parse_blocks_content(raw_content)
    updated_blocks = _wp_apply_block_operations(blocks, operations)
    return _wp_save_blocks(post_id, post_type, updated_blocks)

