@mcp.tool()
def wp_patterns_apply_to_post(
    post_id: int,
    pattern_name: str,
    post_type: str = "post",
    position: int = None,
) -> dict:
    """Insert a block pattern's content into a post at a given position"""
    patterns = _elementor_flatten_items(wp_patterns_list())
    target_name = (pattern_name or "").strip().lower()
    pattern = next(
        (
            item for item in patterns
            if isinstance(item, dict)
            and target_name in {
                str(item.get("name") or "").strip().lower(),
                str(item.get("title") or "").strip().lower(),
            }
        ),
        None,
    )
    if pattern is None:
        raise ValueError(f"Block pattern '{pattern_name}' not found")
    collection = _elementor_content_collection(post_type)
    document = _wp().get(f"/wp/v2/{collection}/{post_id}", params={"context": "edit"})
    content = document.get("content")
    existing_content = content.get("raw") if isinstance(content, dict) else content or ""
    blocks = [part for part in re.split(r"(?=<!-- wp:)", existing_content or "") if part.strip()]
    insert_at = len(blocks) if position is None else max(0, min(position, len(blocks)))
    blocks.insert(insert_at, str(pattern.get("content") or "").strip())
    updated = _wp().post(f"/wp/v2/{collection}/{post_id}", json={"content": "\n\n".join(blocks).strip()})
    return {
        "post_id": post_id,
        "post_type": collection,
        "position": insert_at,
        "pattern": {
            "name": pattern.get("name"),
            "title": pattern.get("title"),
        },
        "post": updated,
    }

