@mcp.tool()
def wp_upload_media_from_url(
    url: str,
    title: str = None,
    alt_text: str = None,
    caption: str = None,
    description: str = None,
    filename: str = None,
) -> dict:
    """Download an image/file from a URL and upload it to WordPress Media Library"""
    import requests as _req
    r = _req.get(url, timeout=30)
    r.raise_for_status()
    ct = r.headers.get("Content-Type", "application/octet-stream").split(";")[0].strip()
    fname = filename or url.rstrip("/").split("/")[-1].split("?")[0] or "upload"
    media = _wp().upload_media(fname, r.content, ct)
    meta = {k: v for k, v in {"title": title, "alt_text": alt_text, "caption": caption, "description": description}.items() if v is not None}
    if meta:
        return _wp().post(f"/wp/v2/media/{media['id']}", json=meta)
    return media

