@mcp.tool()
def wp_bulk_upload_media(
    items: list = None,
) -> dict:
    """Upload multiple images from URLs in one call"""
    import requests as _req
    wp = _wp()
    results = []
    for item in (items or []):
        src = item.get("url") if isinstance(item, dict) else str(item)
        try:
            r = _req.get(src, timeout=30)
            r.raise_for_status()
            ct = r.headers.get("Content-Type", "image/jpeg").split(";")[0].strip()
            fname = src.rstrip("/").split("/")[-1].split("?")[0] or "image.jpg"
            media = wp.upload_media(fname, r.content, ct)
            meta = {k: v for k, v in {k2: item.get(k2) for k2 in ("title", "alt_text", "caption", "description")}.items() if v is not None} if isinstance(item, dict) else {}
            if meta:
                media = wp.post(f"/wp/v2/media/{media['id']}", json=meta)
            results.append({"success": True, "media": media})
        except Exception as exc:
            results.append({"success": False, "url": src, "error": str(exc)})
    return {"results": results, "count": len(results)}

@mcp.tool()
def wp_upload_media_base64(
    base64: str,
    filename: str,
    mime_type: str,
    title: str = None,
    alt_text: str = None,
) -> dict:
    """Upload a file from base64-encoded content"""
    data = base64_lib.b64decode(base64)
    media = _wp().upload_media(filename, data, mime_type)
    meta = {k: v for k, v in {"title": title, "alt_text": alt_text}.items() if v is not None}
    if meta:
        return _wp().post(f"/wp/v2/media/{media['id']}", json=meta)
    return _trim(media)

