@mcp.tool()
def wp_build_menu(
    name: str = None,
    location: str = None,
    items: list = None,
) -> dict:
    """Build a complete menu structure in one call — creates menu and adds all items"""
    result: dict = {}
    # Step 1: create the menu
    menu_resp = _wp().post("/wp/v2/menus", json={"name": name} if name else {})
    menu_id = menu_resp.get("id")
    result["menu"] = menu_resp
    if not menu_id:
        return result
    # Step 2: add items
    if items:
        item_results = []
        for item in items:
            item["menus"] = menu_id
            item_results.append(_wp().post("/wp/v2/menu-items", json=item))
        result["items"] = item_results
    # Step 3: assign to location
    if location:
        result["location"] = _wp().post(f"/wp/v2/menus/{menu_id}", json={"locations": [location]})
    return result

