@mcp.tool()
def wp_list_plugins(
    status: str = "any",
    search: str = None,
    per_page: int = 100,
) -> dict:
    """List all installed WordPress plugins with status (active/inactive)"""
    params = {"context": "edit"}
    if status in ("active", "inactive"): params["status"] = status
    if search is not None: params["search"] = search
    if per_page is not None: params["per_page"] = per_page
    try:
        return _wp().get("/wp/v2/plugins", params=params)
    except requests.HTTPError as exc:
        return _unsupported_from_http(exc, "wp/v2 plugins controller")

