@mcp.tool()
def wp_bulk_activate_plugins(
    plugins: list,
) -> dict:
    """Activate multiple plugins at once. plugins = list of plugin identifiers as returned by wp_list_plugins()"""
    results = {}
    for plugin in plugins:
        try:
            results[plugin] = _wp().put(f"/wp/v2/plugins/{plugin}", json={"status": "active"})
        except Exception as e:
            results[plugin] = {"error": str(e)}
    return results

@mcp.tool()
def wp_bulk_deactivate_plugins(
    plugins: list,
) -> dict:
    """Deactivate multiple plugins at once. plugins = list of plugin identifiers as returned by wp_list_plugins()"""
    results = {}
    for plugin in plugins:
        try:
            results[plugin] = _wp().put(f"/wp/v2/plugins/{plugin}", json={"status": "inactive"})
        except Exception as e:
            results[plugin] = {"error": str(e)}
    return results

