@mcp.tool()
def wp_get_site_info() -> dict:
    """Get site settings, active theme, and high-level counts from verified WordPress controllers."""
    settings = wp_get_site_settings()
    active_theme = wp_get_active_theme()
    info = {
        "name": settings.get("title") or settings.get("blogname"),
        "description": settings.get("description") or settings.get("blogdescription"),
        "url": settings.get("url") or settings.get("home"),
        "home": settings.get("home"),
        "admin_email": settings.get("email") or settings.get("admin_email"),
        "timezone": settings.get("timezone") or settings.get("timezone_string"),
        "language": settings.get("language"),
        "date_format": settings.get("date_format"),
        "time_format": settings.get("time_format"),
        "active_theme": active_theme,
    }
    try:
        plugins = _elementor_flatten_items(_wp().get("/wp/v2/plugins", params={"context": "edit", "per_page": 100}))
        info["plugins_count"] = len(plugins)
        info["active_plugins_count"] = sum(1 for plugin in plugins if plugin.get("status") == "active")
    except requests.HTTPError as exc:
        info["plugins"] = _unsupported_from_http(exc, "wp/v2 plugins controller")
    try:
        users = _wp().get("/wp/v2/users", params={"context": "edit", "per_page": 1})
        if isinstance(users, dict) and "total" in users:
            info["user_count"] = users["total"]
    except requests.HTTPError as exc:
        info["users"] = _unsupported_from_http(exc, "wp/v2 users controller")
    return info

