@mcp.tool()
def wp_list_themes(
    status: str = "any",
    per_page: int = 50,
    search: str = None,
) -> dict:
    """List all installed WordPress themes"""
    params = {"context": "edit"}
    if status in ("active", "inactive"): params["status"] = status
    if per_page is not None: params["per_page"] = per_page
    if search is not None: params["search"] = search
    try:
        return _wp().get("/wp/v2/themes", params=params)
    except requests.HTTPError as exc:
        return _unsupported_from_http(exc, "wp/v2 themes controller")

@mcp.tool()
def wp_get_active_theme() -> dict:
    """Get the currently active WordPress theme details"""
    try:
        result = _wp().get("/wp/v2/themes", params={"context": "edit", "status": "active"})
    except requests.HTTPError as exc:
        return _unsupported_from_http(exc, "wp/v2 themes controller")
    data = result.get("data", result) if isinstance(result, dict) else result
    if isinstance(data, list) and data:
        return data[0]
    return {"active_theme": data}

