@mcp.tool()
def video_upload(
    source_url: str,
    filename: str,
    title: str = None,
    caption: str = None,
    description: str = None,
    alt_text: str = None,
) -> dict:
    """Upload a video file to the WordPress media library from a URL"""
    import requests as _req
    r = _req.get(source_url, timeout=120)
    r.raise_for_status()
    ct = r.headers.get("Content-Type", "video/mp4").split(";")[0].strip()
    fname = filename or source_url.rstrip("/").split("/")[-1].split("?")[0] or "video.mp4"
    media = _wp().upload_media(fname, r.content, ct)
    meta = {k: v for k, v in {"title": title, "caption": caption, "description": description, "alt_text": alt_text}.items() if v is not None}
    if meta:
        return _wp().post(f"/wp/v2/media/{media['id']}", json=meta)
    return media

