@mcp.tool()
def wp_bulk_update_plugins(
    plugins: list,
) -> dict:
    """Update multiple plugins at once"""
    wp = _wp()
    try:
        current = wp.get("/wp/v2/plugins", params={"context": "edit", "per_page": 100})
    except requests.HTTPError as exc:
        current = _unsupported_from_http(exc, "wp/v2 plugins controller")
    return {
        "supported": False,
        "reason": "WordPress core REST API can activate/deactivate/install/delete plugins, but does not expose plugin upgrade execution.",
        "requested_plugins": plugins,
        "installed_plugins": current,
    }

@mcp.tool()
def wp_update_all_plugins() -> dict:
    """Update all plugins that have available updates"""
    try:
        current = _wp().get("/wp/v2/plugins", params={"context": "edit", "per_page": 100})
    except requests.HTTPError as exc:
        current = _unsupported_from_http(exc, "wp/v2 plugins controller")
    return {
        "supported": False,
        "reason": "WordPress core REST API does not expose plugin upgrade execution.",
        "installed_plugins": current,
    }

@mcp.tool()
def wp_get_auto_update_plugins() -> dict:
    """Get list of plugins with auto-updates enabled"""
    try:
        plugins = _wp().get("/wp/v2/plugins", params={"context": "edit", "per_page": 100})
    except requests.HTTPError as exc:
        return _unsupported_from_http(exc, "wp/v2 plugins controller")
    data = plugins.get("data", plugins) if isinstance(plugins, dict) else plugins
    if isinstance(data, list):
        return [p for p in data if isinstance(p, dict) and p.get("auto_update") is True]
    return plugins

